from save_review import save
save(1186,{2:'加速加农炮又称残暴刃加农炮，其双联型号是残暴刃的主武器。这种先进火炮由泰格鲁斯铸造世界研制，能够在两类弹药之间切换：以致密弹芯穿甲弹对付敌方装甲，或以威力强大的高爆破片弹攻击步兵。',6:'这种火炮采用基于特殊真空系统的复杂超压机构，能以超过同等尺寸常规火炮的推力发射重型炮弹。系统效率极高，每次发射产生的后坐力很小，因而稳定性和精度出众。先进的装填机构还允许车长迅速切换弹种。',8:'加速加农炮可使用两类弹药。第一类是带破片弹芯的重型高爆反人员弹，一发便足以扫灭整支部队；第二类是带超致密弹芯的反装甲弹，能够贯穿所有已知类别的实体装甲。两类弹药均由复杂的逻辑引擎系统辅助瞄准，该系统与星际战士车长的战术指挥终端联动，使他能搜索并在数十个目标之间切换。'},{8:'原“加速自动炮”与本条cannon名称不一致，统一加速加农炮；原英文anti-personal应指反人员，按语境译。'},[('Accelerator Cannon','加速加农炮'),('Fellblade Cannon','残暴刃加农炮')])
save(1187,{2:'破坏者加农炮是一种短射程、大口径直射火炮，可安装在多种帝国载具上，最常见的搭载平台是毒刃、黎曼鲁斯破坏者与维护者战车。它主要为攻城、巷战和摧毁掩体而设计，也能轻易击毁敌方载具、杀伤步兵。',7:'破坏者加农炮发射的专用炮弹远大于战斗炮弹，足以贯穿层层混凝土和塑钢。炮弹的化学核心外包覆着常规高爆装药与破片。命中时，外层装药先行爆炸，在装甲上炸开缺口，并向四周抛撒破片；同时，核心内发生化学反应，急剧升温形成等离子射流，沿破口灌入目标内部，将其由内向外撕裂。开炮时的巨大后坐力足以将坦克前部抬离地面，若在行进中发射，甚至可能造成侧翻。火炮有效射程约一千米，因此主要用于巷战、攻城等近距离交战。',9:'维护者战车使用的破坏者加农炮发射专用攻城弹，由穿甲弹尖、厚重弹壳与大装药构成，并配有微型引信，使炮弹先穿入建筑或掩体，再行爆炸。弹载火箭发动机负责推进，固体推进剂的形状经过设计，以控制燃烧时间和速率、提高精度。火炮发射时会排出反冲燃气，避免积聚的高压使炮管变形或爆裂。但炮弹体积和重量都很大，即使配有稳定尾翼并采用助推燃烧，车内备弹量与远距离精度仍受到限制。因此，它主要用于摧毁防御工事，以及丛林战等近距离战斗。'},
{7:'弹药机理为底稿的虚构设定，照译，不以现实化学或弹道知识改写其原理。',9:'原译遗漏massive explosive charge大装药，将炮弹写成只有弹尖、弹壳和引信，已补回。'},[('Demolisher Cannon','破坏者加农炮')],title='破坏者加农炮 Demolisher Cannon')
save(1188,{2:'巨型加速加农炮是帝国阿斯特赖俄斯超重型坦克使用的一种武器。这种复杂的质量加速炮能连续射出大口径铁碳化物弹丸，形成连重装甲也难以承受的密集弹幕。'},terms=[('Macro-Accelerator Cannon','巨型加速加农炮')])
save(1189,{2:'恐惧之锤加农炮是安装在提丰重型攻城坦克上的巨型帝国火炮，相当于将一门庞大的固定式重炮搬上载具底盘。每发重达数吨的炮弹所产生的动能冲击，足以将血肉和骨骼震成液状；即使防护最严密的掩体，也难以抵挡它的轰击。'},terms=[('Dreadhammer Cannon','恐惧之锤加农炮'),('Dreadhammer Siege Cannon','恐惧之锤攻城炮')])
save(1190,{2:'疫病重型臼炮是大远征和荷鲁斯之乱期间星际战士军团使用的一种武器。',4:'Arquitor Bombard with Morbus Heavy Bombard 装备疫病重型臼炮的曲射手臼炮载具',6:'疫病重型臼炮安装在曲射手臼炮载具上，以更常见的破坏者加农炮为设计蓝本，其炮弹足以重创防护最严密的装甲部队。除爆炸弹药外，它还可发射死尸炮弹；其中装填的生物制剂，能在数秒内将毫无装甲防护的战士化为四散血肉。',8:'莫塔里安对这种武器印象极深，后来将其设计融入了瘟爆履带战车。'},terms=[('Morbus Heavy Bombard','疫病重型臼炮'),('Arquitor Bombard','曲射手臼炮载具'),('Carcass Shells','死尸炮弹')])
locke='标准洛克型帝国导弹发射器内置瞄准装置，采用肩射方式，每次装填一发，不能边移动边射击。按照帝国卫队的通常编制，一人负责携行、瞄准和发射，另一人携带弹药并负责装填。配合熟练的小组能够维持惊人的射速，让最勇敢的坦克指挥官也心生忌惮。帝国卫队需要小组协同操作，星际战士则凭借强大体力，可以独自携行、射击和装填。'
save(1191,{2:'导弹发射器发射带制导能力的自推进弹药，通常装有爆炸、化学或破坏性能量弹头。推进方式可以是化学火箭发动机、喷气发动机，也可能是反重力驱动等更特殊的技术。',4:'火箭发射器发射不带制导能力的自推进弹药，可采用与导弹相同的各类弹头。火箭通常以放热化学反应提供推力，但也可使用其他推进方式。',8:locke,11:'Ork 欧克',17:'超级火箭——践踏巨机使用的武器。',19:'巡航导弹——加冈特使用的武器。',23:'坦爆火箭——欧克陆地方舟使用的武器。',30:'灵族导弹发射器是灵族地面部队的标准导弹武器。它不采用帝国惯用的简单发射管，而是将破甲、等离子等多种弹头存放在复杂的分舱式发射舱内，大幅减少重新装填的需要。弹药十分紧凑，单具发射器就能容纳数十发。尽管可由单兵携行，它仍更常见于反重力平台或灵族载具上。',34:'黑暗死神是灵族的一种支派战士，携带能够快速发射穿甲导弹的收割者发射器。',36:'暴风发射器是一种能进行间接射击的多管导弹发射器，由黑暗死神主教使用。',46:'混沌星际战士既使用荷鲁斯之乱前配发的旧式导弹发射器，也使用从战败敌军手中缴获的现代帝国型号。多数型号与帝国武器的操作方式相同，此外他们也使用浩劫发射器。',52:'混沌污染者可装备重型导弹发射器。',55:'钛族的远程武器技术，包括导弹发射器技术，比帝国更先进。不过，钛军的组织方式与其他种族不同，普通士兵不携带导弹发射器；这里列举的两类发射系统都搭载在战斗服上。',57:'导弹吊舱可安装在 XV8 危机战斗服上，也是 XV-81 与 XV-84 的标准装备。它发射中程速射导弹，单发威力略低于帝国破甲导弹。得益于紧凑的尺寸和战斗服平台，吊舱能够在移动中开火。',59:'智能导弹系统代表战斗服导弹技术的高峰，威力适中，射速可达导弹吊舱的两倍。先进的制导技术使射手无需与目标之间保持直达视线：每枚导弹都能绕过地形和障碍物命中目标，让射手不必暴露在危险中。按本条所述，其尺寸限制了搭载平台，只能安装在庞大的舷炮战斗服上；若无额外稳定装置，也无法在移动中射击。',70:'APM 发射器——可按需切换弹头种类的自适应武器。',72:'L7 导弹发射器——一个导弹系统系列。'},
{46:'原译将叛乱前配发的武器也一并写成缴获品，已区分配发旧械和缴获现代型号。',55:'本段“两类”只与紧接的吊舱、智能系统说明对应，后续清单另有多种导弹，保留底稿范围差异。',59:'line of sight是直达视线，不是无需瞄准；只可搭载舷炮、移动开火限制等属底稿所述版本，不擅自套入当前桌面规则。'},
[('Missile Launcher','导弹发射器'),('Rocket Launcher','火箭发射器'),('Locke-pattern Imperial Missile Launcher','洛克型帝国导弹发射器'),('Rokkit Launcha','欧克火箭发射器'),('Supa-Rokkit','超级火箭'),('Krooz Missiles','巡航导弹'),('Skorcha Missiles','炙烤导弹'),('Tankbusta Rokkits','坦爆火箭'),('Grot Bombs','屁精炸弹'),('Pulsa Rokkit','脉冲火箭'),('Eldar Missile Launcher','灵族导弹发射器'),('Reaper Launcher','收割者发射器'),('Tempest Launcher','暴风发射器'),('Phantom Missile Launcher','幻影导弹发射器'),('Phoenix Missile Launcher','凤凰导弹发射器'),('Void Raven Missile Launcher','虚空鸦导弹发射器'),('Havoc Launcher','浩劫发射器'),('Hellfyre Missile Rack','地狱火导弹架'),('Missile Pod','导弹吊舱'),('Smart Missile System','智能导弹系统'),('Seeker Missile','探求者导弹'),('Cluster Rocket System','集群火箭系统'),('Destroyer Missile','毁灭者导弹'),('Nexus Missile System','连携导弹系统'),('APM Launcher','APM 发射器'),('L7 Missile Launcher','L7 导弹发射器'),('Sagitaur Missile Launcher','人马座导弹发射器')])
save(1192,{7:locke,10:'Man-Portable 单兵便携式',16:'阿基兰 Mk.III“羽距”导弹发射器——帝国卫队武器小组使用的紧凑型发射器。',18:'盔甲杀手导弹发射器——杰里科疆域死亡守望独有的型号。它外形低矮粗壮，宽口径发射管约有星际战士半人高，专门用于对付地面重装甲目标。它通常装填猎杀破甲导弹，配有鸟卜仪阵列与专用沉思者，辅助导弹精确制导，效能高于音袭型发射器。特殊鸟卜仪阵列兼具猎感瞄具与红点激光瞄具的优势。',24:'超级破片火箭发射器——星际战士寂灭小队使用的武器。',26:'超级穿甲火箭发射器——星际战士寂灭小队使用的武器。',28:'威格尔发射器——星际战士寂灭小队使用的武器。',30:'堡主发射器——星际战士寂灭小队使用的武器。',34:'普罗透斯型——源自大远征与荷鲁斯之乱时期的古老重型设计，可以快速连续发射多枚导弹，当年专供阿斯塔特军团使用。如今，仍有少数星际战士战团装备这种型号。',38:'雷托比型导弹发射器——采用五发弹夹供弹的古老型号。它的射速较快，但精度较低，操作和射击也更加不便。',42:'音袭型——星际战士标准单管导弹发射器的另一种选择。它把专用导弹架与自动装填器安装在动力背包上；射击时，装填器的机械爪迅速从背后取弹，填入发射器。因此，只要导弹架尚未打空，战士便能连续发射所需弹种。黑暗天使使用的 Mk.V 型音袭发射器更加紧凑。'},
{16:'英文称compact missile，结合标题及全条语境应为发射器；原Tread Fether疑为口语化型号别称，暂沿羽距并标官方待核。',18:'squat描述低矮粗壮的外形，不是蹲姿；cogitators为沉思者，不是定位器。'},
[('Imperial Missile Launcher','帝国导弹发射器'),('Accatran Pattern Missile Launcher','阿卡特兰型导弹发射器'),('Achillan Mk III Tread Fether Missile Launcher','阿基兰 Mk.III 羽距导弹发射器'),('Armourbane Missile Launcher','盔甲杀手导弹发射器'),('Fury Pattern Missile Launcher','狂怒型导弹发射器'),('Superfrag Rocket Launcher','超级破片火箭发射器'),('Superkrak Rocket Launcher','超级穿甲火箭发射器'),('Vengor Launcher','威格尔发射器'),('Castellan Launcher','堡主发射器'),('Cyclone Missile Launcher','旋风导弹发射器'),('Proteus Pattern Missile Launcher','普罗透斯型导弹发射器'),('Retobi Pattern Missile Launcher','雷托比型导弹发射器'),('Rocket Propelled Grenade','火箭榴弹'),('Soundstrike Pattern Missile Launcher','音袭型导弹发射器'),('Thunderbolt Pattern Missile Launcher','霹雳型导弹发射器'),('Vratine Missile Launcher','弗拉廷导弹发射器')])
save(1193,{2:'辐射导弹是大远征和荷鲁斯之乱期间使用的一种辐射武器。',6:'这种源自泰拉的导弹，是纷争时代基因战争留下的恐怖兵器。特制弹头将高爆破片装药与放射性同位素结合，制造出剧毒般的强烈辐射；无论受害者多么顽强，都难逃惨死。由于污染严重、手段酷烈，它很少投入使用，最常见的操作者是星际战士毁灭者。'},terms=[('Rad Missile Launcher','辐射导弹发射器')])
save(1194,{2:'堡主发射器是原铸星际战士寂灭小队使用的一种火箭发射器。',4:'这类弹链供弹的辅助武器附装在寂灭小队的其他火箭发射器上，包括超级穿甲、超级破片和威格尔发射器。它能向空中倾泻小型制导炸弹，尤其适合逼迫敌人离开掩体。'},terms=[('Castellan Launcher','堡主发射器')])
save(1195,{2:'威格尔发射器是一种由原铸星际战士寂灭小队军士使用的导弹发射器。',5:'威格尔发射器附带一具弹链供弹、可以独立射击的堡主发射器。两者配合，能够发挥强大的间接火力，甚至在敌人进入视野之前，就将整支小队消灭。',7:'Desolation Squad Vengor Launcher 寂灭小队的威格尔发射器'},terms=[('Vengor Launcher','威格尔发射器')])
